import { describe, expect, it, vi, beforeEach } from 'vitest';

/* appendChangeLog inserts into the changelog table, which has `id uuid primary key default gen_random_uuid()`.
   The function used to generate its own non-UUID id with newId('log'), which Postgres rejects as an
   invalid syntax for type uuid. This test verifies the fix: the insert payload no longer includes
   an explicit id, letting the database supply it. */
vi.mock('../repo.js', () => ({
  supabaseAdmin: {
    from: vi.fn().mockReturnValue({
      insert: vi.fn(),
    }),
  },
  newId: vi.fn(),
  nowIso: vi.fn(),
}));

import * as repo from '../repo.js';
import { pgPool } from '../pgPool.js';
import type { ChangeLogEntry } from '@asohav/shared';

describe('appendChangeLog', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.mocked(repo.nowIso).mockReturnValue('2026-01-01T00:00:00.000Z');
  });

  it('omits the id key from the insert payload', async () => {
    const entry: Omit<ChangeLogEntry, 'Id' | 'At'> = {
      Who: 'Test User',
      Action: 'create' as const,
      Collection: 'virtues',
      ObjectId: 'v-test',
      ObjectName: 'Test Virtue',
      Before: null,
      After: { Id: 'v-test', Name: 'Test', Tagline: 'Testing' },
    };

    await repo.appendChangeLog(entry);

    expect(vi.mocked(repo.supabaseAdmin).from).toHaveBeenCalledWith('changelog');
    const insertPayload = (vi.mocked(repo.supabaseAdmin).from as any).mock.calls[0][0].insert.mock.calls[0][0];
    expect(insertPayload).not.toHaveProperty('id');
  });

  it('includes all the changelog columns correctly mapped to snake_case', async () => {
    const entry: Omit<ChangeLogEntry, 'Id' | 'At'> = {
      Who: 'Test User',
      Action: 'update' as const,
      Collection: 'bonds',
      ObjectId: 'bond-123',
      ObjectName: 'Hero Bond',
      Before: { Id: 'bond-123', Name: 'Old Bond' },
      After: { Id: 'bond-123', Name: 'New Bond' },
    };

    await repo.appendChangeLog(entry);

    const insertPayload =
      (vi.mocked(repo.supabaseAdmin).from as any).mock.calls[0][0].insert.mock.calls[0][0];

    // Verify at is included (generated by nowIso)
    expect(insertPayload.at).toBe('2026-01-01T00:00:00.000Z');

    // Verify entity fields
    expect(insertPayload.who).toBe(entry.Who);
    expect(insertPayload.action).toBe(entry.Action);
    expect(insertPayload.collection).toBe(entry.Collection);
    expect(insertPayload.object_id).toBe(entry.ObjectId);
    expect(insertPayload.object_name).toBe(entry.ObjectName);
    expect(insertPayload.before).toBe(entry.Before);
    expect(insertPayload.after).toBe(entry.After);

    // Verify no camelCase fields leak through
    expect(insertPayload).not.toHaveProperty('who');
    expect(insertPayload).not.toHaveProperty('action');
    expect(insertPayload).not.toHaveProperty('collection');
    expect(insertPayload).not.toHaveProperty('ObjectId');
    expect(insertPayload).not.toHaveProperty('ObjectName');
    expect(insertPayload).not.toHaveProperty('Before');
    expect(insertPayload).not.toHaveProperty('After');
  });

  it('does not call newId since we let the DB generate the uuid', async () => {
    const entry: Omit<ChangeLogEntry, 'Id' | 'At'> = {
      Who: 'Test',
      Action: 'create',
      Collection: 'test',
      ObjectId: 'obj-1',
      ObjectName: 'Test Object',
      Before: null,
      After: null,
    };

    await repo.appendChangeLog(entry);

    expect(vi.mocked(repo.newId)).not.toHaveBeenCalled();
  });

  it('propagates the error from the insert call', async () => {
    const mockError = new Error('Database error');
    vi.mocked(repo.supabaseAdmin.from).mockReturnValue({
      insert: vi.fn().mockRejectedValue(mockError),
    });

    await expect(repo.appendChangeLog({
      Who: 'Test',
      Action: 'create',
      Collection: 'test',
      ObjectId: 'obj-1',
      ObjectName: 'Test',
      Before: null,
      After: null,
    })).rejects.toThrow(mockError);
  });
});

