    expect(repo.newId).not.toHaveBeenCalled();
  });

  it('propagates the error from the insert call', async () => {
    const mockError = new Error('Database error');
    const errorFrom = vi.fn().mockReturnValue({
      insert: vi.fn().mockRejectedValue(mockError),
    });
